using System;\nusing NUnit.Framework;\nusing RestSharp;\nusing TechTalk.SpecFlow;\nusing AutomationFramework.API.BusinessLogic;\nusing AutomationFramework.Core.Utilities;\nusing Serilog;\nusing Newtonsoft.Json;\n\nnamespace AutomationFramework.API.StepDefinitions\n{\n    [Binding]\n    public class PetstoreSteps\n    {\n        private readonly ScenarioContext _scenarioContext;\n        private readonly PetApiHelper _petApiHelper;\n        private RestResponse _response;\n\n        public PetstoreSteps(ScenarioContext scenarioContext)\n        {\n            _scenarioContext = scenarioContext;\n            _petApiHelper = new PetApiHelper();\n        }\n\n        [Given(@\"the API endpoint is \"\"(.*)\"\"\")]\n        public void GivenTheApiEndpointIs(string endpoint)\n        {\n            _scenarioContext[\"Endpoint\"] = endpoint;\n            Log.Information(\"Endpoint set to: {Endpoint}\", endpoint);\n        }\n\n        [When(@\"I send a POST request with payload\")]\n        public void WhenISendAPostRequestWithPayload()\n        {\n            var payload = new { id = 123, name = \"doggie\", status = \"available\" };\n            _response = _petApiHelper.SendPostRequest((string)_scenarioContext[\"Endpoint\"], payload);\n            Log.Information(\"POST request sent with payload: {Payload}\", JsonConvert.SerializeObject(payload));\n        }\n\n        [When(@\"I send a GET request with pet ID\")]\n        public void WhenISendAGetRequestWithPetId()\n        {\n            var petId = 123;\n            _response = _petApiHelper.SendGetRequest((string)_scenarioContext[\"Endpoint\"].Replace(\"{petId}\", petId.ToString()));\n            Log.Information(\"GET request sent for pet ID: {PetId}\", petId);\n        }\n\n        [When(@\"I send a PUT request with payload\")]\n        public void WhenISendAPutRequestWithPayload()\n        {\n            var payload = new { id = 123, name = \"doggie\", status = \"sold\" };\n            _response = _petApiHelper.SendPutRequest((string)_scenarioContext[\"Endpoint\"], payload);\n            Log.Information(\"PUT request sent with payload: {Payload}\", JsonConvert.SerializeObject(payload));\n        }\n\n        [When(@\"I send a DELETE request with pet ID\")]\n        public void WhenISendADeleteRequestWithPetId()\n        {\n            var petId = 123;\n            _response = _petApiHelper.SendDeleteRequest((string)_scenarioContext[\"Endpoint\"].Replace(\"{petId}\", petId.ToString()));\n            Log.Information(\"DELETE request sent for pet ID: {PetId}\", petId);\n        }\n\n        [Then(@\"the response status code should be 200\")]\n        public void